prop("N001","For every natural m, subset A⊆R^m and positive real s, H^s(A)=μH[s](A). Consequently: if s>dim_H(A) then H^s(A)=0; if 0<s<dim_H(A) then H^s(A)=infinity; H^s(A)=0 implies dim_H(A)≤s; H^s(A)=infinity implies dim_H(A)≥s. Dimension is nonnegative, including for the empty set.",["m","A","s","H","μH","dim_H"],["D001","D002","D003","D004"],[b("m","natural number"),b("A","subset of Euclidean R^m"),b("s","positive real number")]),
prop("N002","D is finite and 0≤D≤n. If n=0, then E=R^0 is a singleton and D=0. For every positive real s and delta, H^s_delta(E) is finite.",["n","E","D","H","s","delta"],["D001","D002","D004","D007"],[b("s","positive real number"),b("delta","positive real number")]),
prop("N003","dim_H(I)=1. For every a>1, H^a(I)=0, and for every s with 0<s<1, H^s(I)=infinity.",["I","dim_H","H","a","s"],["D001","D002","D004","D005","D008"],[b("a","real number"),b("s","real number")]),
prop("N004","dim_H(F)≤D+1, and in particular dim_H(F) is finite.",["F","D","dim_H"],["D004","D006","D007"]),
prop("N005","For every real s>0 and delta>0, H^s_delta(E)≤H^(s+1)_delta(F).",["s","delta","E","F","H"],["D001","D002","D005","D006"],[b("s","real number"),b("delta","real number")]),
prop("N006","If D>0, then dim_H(F)≥D+1.",["D","F","dim_H"],["D004","D006","D007"]),
prop("N007","If D=0, then dim_H(F)≥1=D+1; this includes n=0.",["D","F","n","dim_H"],["D004","D006","D007"]),
prop("P","dim_H(E×[0,1])=dim_H(E)+1, with R^n×R identified with Euclidean R^(n+1), including n=0.",["E","n","dim_H"],["D004","D005","D006"])
